13	// NewPortsDataMsg hands socket rows to the Ports view without reading the real
14	// socket table (guard seed, DEVDESK-150 H8).
15	func NewPortsDataMsg(sockets []ports.Socket) tea.Msg { return portsDataMsg{ports: sockets} }
16	
17	// defaultPortsRefresh is what the interval falls back to. A non-positive one —
18	// a hand-edited 0 in the config — would make tea.Tick fire without pausing and
19	// spin a docker exec per frame, so it is refused here rather than trusted.
20	const defaultPortsRefresh = 2 * time.Second
21	
22	func portsTickCmd(every time.Duration) tea.Cmd {
23		if every <= 0 {
24			every = defaultPortsRefresh
25		}
26		return tea.Tick(every, func(time.Time) tea.Msg {
27			return portsTickMsg{}
28		})
29	}
30	
31	// portsFetchTimeout bounds one read. Reverse DNS is the part that can hang —
32	// the socket table itself is a system call — and a fetch outliving several
33	// ticks would stack one behind another.
34	const portsFetchTimeout = 5 * time.Second
35	
36	func fetchPortsCmd(numeric bool) tea.Cmd {
37		return func() tea.Msg {
38			ctx, cancel := context.WithTimeout(context.Background(), portsFetchTimeout)
39			defer cancel()
40			sockets, err := ports.List(ctx, !numeric)
41			return portsDataMsg{ports: sockets, err: err}
42		}
43	}
44	
45	// processOps is what the Ports tab does to the machine's processes, held in
46	// one value so a test can replace it and no test signals a real process.
47	type processOps struct {
48		// kill ends the process with this PID.
49		kill func(pid string) error
50		// windows says the platform has no clean stop, which changes the wording
51		// of the confirmation and of the help, nothing else.
52		windows bool
53	}
54	
55	// realProcessOps is the production wiring: ports.Kill on the platform the
56	// binary runs on.
57	func realProcessOps() processOps {
58		return processOps{kill: ports.Kill, windows: runtime.GOOS == "windows"}
59	}
60	
61	// killProcessCmd signals pid through kill. Both are values captured in
62	// Update (Rule 110): the command never reads the model.
63	func killProcessCmd(kill func(string) error, pid string) tea.Cmd {
64		return func() tea.Msg {
65			return portsKillResultMsg{pid: pid, err: kill(pid)}
66		}
67	}
